import{_ as a,o,c as t,ag as i}from"./chunks/framework.CrXGS008.js";const w=JSON.parse('{"title":"Frameworki i zasoby","description":"","frontmatter":{},"headers":[],"relativePath":"pl/bridge/index.md","filePath":"pl/bridge/index.md"}'),n={name:"pl/bridge/index.md"};function r(d,e,s,c,p,y){return o(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="frameworki-i-zasoby" tabindex="-1">Frameworki i zasoby <a class="header-anchor" href="#frameworki-i-zasoby" aria-label="Permalink to &quot;Frameworki i zasoby&quot;">​</a></h1><p>Każdy skrypt Nayretis komunikuje się z Twoim serwerem przez bridge <code>nay_lib</code>. Przy pierwszym użyciu wykrywa on framework, ekwipunek, target i powiadomienia, dzięki czemu ten sam skrypt działa na każdym obsługiwanym zestawie.</p><h2 id="obsługiwane-zestawy" tabindex="-1">Obsługiwane zestawy <a class="header-anchor" href="#obsługiwane-zestawy" aria-label="Permalink to &quot;Obsługiwane zestawy&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Moduł</th><th>Adaptery</th><th>Rozwiązanie zapasowe</th></tr></thead><tbody><tr><td>Framework</td><td><code>qbox</code> (qbx_core), <code>ox</code> (ox_core), <code>esx</code> (es_extended), <code>qbcore</code> (qb-core), <code>custom</code></td><td>brak, skrypt zatrzymuje się z błędem</td></tr><tr><td>Ekwipunek</td><td><code>ox_inventory</code>, <code>qs-inventory</code>, <code>qb-inventory</code></td><td><code>framework</code> (własny ekwipunek frameworka)</td></tr><tr><td>Target</td><td><code>ox_target</code>, <code>qb-target</code></td><td><code>none</code> (podpowiedzi klawiszy)</td></tr><tr><td>Powiadomienia</td><td><code>ox_lib</code>, <code>nayretis</code> (tylko po wymuszeniu)</td><td><code>framework</code>, potem <code>native</code> (feed GTA)</td></tr></tbody></table><p>Wykrywanie przebiega w kolejności z tabeli. Uruchamiaj <code>nay_lib</code> <strong>po</strong> zasobach frameworka, ekwipunku i targetu, inaczej nie zostaną wykryte.</p><h2 id="wymuszenie-adaptera" tabindex="-1">Wymuszenie adaptera <a class="header-anchor" href="#wymuszenie-adaptera" aria-label="Permalink to &quot;Wymuszenie adaptera&quot;">​</a></h2><p>Jeśli wykrywanie wybierze zły zasób, wymuś go w <code>server.cfg</code> przez <code>setr</code> (klient też go odczytuje):</p><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>setr nay:framework &quot;esx&quot;</span></span>
<span class="line"><span>setr nay:inventory &quot;ox_inventory&quot;</span></span>
<span class="line"><span>setr nay:target &quot;ox_target&quot;</span></span>
<span class="line"><span>setr nay:notify &quot;native&quot;</span></span></code></pre></div><p>Wartości to nazwy adapterów z tabeli powyżej albo <code>auto</code> (domyślnie). Zobacz <a href="/pl/nay-lib/convars">Convary</a>.</p><p>Używasz frameworka spoza listy? Napisz <a href="/pl/bridge/custom">własny adapter</a>.</p><h2 id="znane-ograniczenia" tabindex="-1">Znane ograniczenia <a class="header-anchor" href="#znane-ograniczenia" aria-label="Permalink to &quot;Znane ograniczenia&quot;">​</a></h2><ul><li><strong>ox_core</strong>: nie ma flagi służby, więc aktywna grupa jest traktowana jako zawód na służbie. Najwyższa ranga grupy liczy się jako szef.</li><li><strong>ox_inventory</strong> (dowolny framework): przedmioty do użycia muszą istnieć w <code>ox_inventory/data/items.lua</code>. ox_inventory wywołuje callback przedmiotu tylko dla przedmiotów bez <code>consume</code>, <code>client.export</code> ani <code>server.export</code>.</li><li><strong>qb-inventory</strong>: metadane przedmiotów są ignorowane przy liczeniu przedmiotów.</li><li><strong>qs-inventory</strong>: wyniki dodawania i usuwania przedmiotów nie są udokumentowane. Każdy wynik inny niż <code>false</code> jest traktowany jako sukces.</li><li><strong>ESX</strong>: powiadomienia używają <code>esx_notify</code>, gdy jest uruchomiony, w przeciwnym razie feedu GTA.</li></ul>`,12)])])}const u=a(n,[["render",r]]);export{w as __pageData,u as default};
